package recording

import (
	"encoding/json"
	"os"
	"reflect"
	"strings"
	"testing"

	"github.com/streamhubstudio/streamhub/streamhub-core-go/internal/contracts"
	"github.com/streamhubstudio/streamhub/streamhub-core-go/internal/platform/yamljs"
)

// Cross-runtime vectors generated by testdata/gen-transcode-vectors.js from
// the Node core's dist build.

type tcVectors struct {
	Argv []struct {
		Name string   `json:"name"`
		Bin  string   `json:"bin"`
		Args []string `json:"args"`
	} `json:"argv"`
	Ladders []struct {
		Name string `json:"name"`
		Cfg  struct {
			Transcoding struct {
				VodRenditions []contracts.VodRendition `json:"vodRenditions"`
			} `json:"transcoding"`
			Webrtc struct {
				Layers []contracts.WebrtcLayer `json:"layers"`
			} `json:"webrtc"`
		} `json:"cfg"`
		Out []contracts.VodRendition `json:"out"`
	} `json:"ladders"`
	Bitrates []struct{ H, Out float64 } `json:"bitrates"`
	Widths   []struct {
		H   float64  `json:"h"`
		W   *float64 `json:"w"`
		SH  *float64 `json:"sh"`
		Out float64  `json:"out"`
	} `json:"widths"`
	Masters []struct {
		Name    string `json:"name"`
		Entries []struct {
			URI         string   `json:"uri"`
			Height      float64  `json:"height"`
			BitrateKbps float64  `json:"bitrateKbps"`
			Width       *float64 `json:"width"`
		} `json:"entries"`
		Out string `json:"out"`
	} `json:"masters"`
	RawKeys []struct {
		Name   string         `json:"name"`
		Keys   DrmContentKeys `json:"keys"`
		Scheme string         `json:"scheme"`
		Out    []string       `json:"out"`
	} `json:"rawKeys"`
	ShakaJobs []struct {
		Name string `json:"name"`
		Job  struct {
			Renditions []struct {
				Height  float64 `json:"height"`
				Mp4Path string  `json:"mp4Path"`
			} `json:"renditions"`
			AudioSourcePath string   `json:"audioSourcePath"`
			OutDir          string   `json:"outDir"`
			SegmentSeconds  float64  `json:"segmentSeconds"`
			KeyArgs         []string `json:"keyArgs"`
		} `json:"job"`
		Out []string `json:"out"`
	} `json:"shakaJobs"`
	Drm []struct {
		Disk json.RawMessage       `json:"disk"`
		Out  contracts.DrmFeatures `json:"out"`
	} `json:"drm"`
}

func loadTcVectors(t *testing.T) tcVectors {
	t.Helper()
	b, err := os.ReadFile("testdata/transcode_vectors.json")
	if err != nil {
		t.Fatal(err)
	}
	var v tcVectors
	if err := json.Unmarshal(b, &v); err != nil {
		t.Fatal(err)
	}
	return v
}

func TestVectorFfmpegArgv(t *testing.T) {
	for _, v := range loadTcVectors(t).Argv {
		var got []string
		parts := strings.SplitN(v.Name, "-", 2)
		switch {
		case parts[0] == "hls" || parts[0] == "hls6" || parts[0] == "mp4":
			r := ladderStep(v.Name)
			seg := 4
			if parts[0] == "hls6" {
				seg = 6
			}
			if parts[0] == "mp4" {
				got = RenditionMp4Args("/W/src.mp4", "/W/mezz/"+xcNum(r.Height)+"p.mp4", r)
			} else {
				got = HlsRenditionArgs("/W/src.mp4", "/W/"+xcNum(r.Height)+"p", r, seg)
			}
		case v.Name == "webm-default":
			got = WebmVp8Args("/W/src.mp4", "/W/a.webm", 2500)
		case v.Name == "webm-1400":
			got = WebmVp8Args("/W/src.mp4", "/W/a.webm", 1400)
		case v.Name == "webm-frac":
			got = WebmVp8Args("/W/src.mp4", "/W/a.webm", 3782.5)
		default:
			t.Fatalf("unmapped vector %s", v.Name)
		}
		if v.Bin != "ffmpeg" || !reflect.DeepEqual(got, v.Args) {
			t.Errorf("%s:\n go   %q\n node %q", v.Name, got, v.Args)
		}
	}
}

func ladderStep(name string) contracts.VodRendition {
	switch {
	case strings.HasSuffix(name, "-720"):
		return contracts.VodRendition{Height: 720, BitrateKbps: 2800}
	case strings.HasSuffix(name, "-1080"):
		return contracts.VodRendition{Height: 1080, BitrateKbps: 5000}
	case strings.HasSuffix(name, "-361"):
		return contracts.VodRendition{Height: 361, BitrateKbps: 1263.5}
	}
	return contracts.VodRendition{Height: 144, BitrateKbps: 250}
}

func TestVectorLaddersAndMath(t *testing.T) {
	v := loadTcVectors(t)
	for _, l := range v.Ladders {
		cfg := &contracts.AppConfig{}
		cfg.Transcoding.VodRenditions = l.Cfg.Transcoding.VodRenditions
		cfg.Webrtc.Layers = l.Cfg.Webrtc.Layers
		if got := ResolveVodRenditions(cfg); !reflect.DeepEqual(got, l.Out) {
			t.Errorf("ladder %s: go %v node %v", l.Name, got, l.Out)
		}
	}
	for _, b := range v.Bitrates {
		if got := BitrateForHeight(b.H); got != b.Out {
			t.Errorf("bitrate %v: go %v node %v", b.H, got, b.Out)
		}
	}
	for _, w := range v.Widths {
		if got := WidthForHeight(w.H, w.W, w.SH); got != w.Out {
			t.Errorf("width %v %v %v: go %v node %v", w.H, w.W, w.SH, got, w.Out)
		}
	}
	for _, m := range v.Masters {
		var entries []MasterPlaylistEntry
		for _, e := range m.Entries {
			entries = append(entries, MasterPlaylistEntry{e.URI, e.Height, e.BitrateKbps, e.Width})
		}
		if got := BuildMasterPlaylist(entries); got != m.Out {
			t.Errorf("master %s:\n go   %q\n node %q", m.Name, got, m.Out)
		}
	}
}

func TestVectorDrmArgv(t *testing.T) {
	v := loadTcVectors(t)
	for _, k := range v.RawKeys {
		if got := BuildRawKeyArgs(k.Keys, k.Scheme); !reflect.DeepEqual(got, k.Out) {
			t.Errorf("raw keys %s:\n go   %q\n node %q", k.Name, got, k.Out)
		}
	}
	for _, j := range v.ShakaJobs {
		job := ShakaHlsJob{AudioSourcePath: j.Job.AudioSourcePath, OutDir: j.Job.OutDir, SegmentSeconds: j.Job.SegmentSeconds, KeyArgs: j.Job.KeyArgs}
		for _, r := range j.Job.Renditions {
			job.Renditions = append(job.Renditions, ShakaRendition{r.Height, r.Mp4Path})
		}
		if got := BuildShakaHlsArgs(job); !reflect.DeepEqual(got, j.Out) {
			t.Errorf("shaka %s:\n go   %q\n node %q", j.Name, got, j.Out)
		}
	}
	for i, d := range v.Drm {
		disk, _ := yamljs.ParseJSON(d.Disk)
		if got := ResolveDrmFeatures(disk); !reflect.DeepEqual(got, d.Out) {
			t.Errorf("drm %d (%s):\n go   %+v\n node %+v", i, d.Disk, got, d.Out)
		}
	}
}
